    @Override public void onCreate(Bundle state){super.onCreate(state);store=Store.get(this);if(state!=null){coverId=state.getString("coverId","");coverPlaylist=state.getBoolean("coverPlaylist");afterFolder=state.getInt("afterFolder");}draw();handler.post(tick);handleShare(getIntent());if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},50);}
